/**
 * Connector fidelity Plan A Task 14 (spec §10) -- the messy corpora, in the REAL editor.
 *
 * `__fixtures__/connector_corpora/*.json` is what the server engine STORED for a messy Notion
 * workspace and a messy Obsidian vault (generated by
 * `api/services/journal_two/note_connectors/corpora/corpora_gen.py`; the Python rail
 * `test_connector_corpora.py` keeps the files current and asserts the stored documents).
 * Here every stored body is mounted through `buildExtensions()`, read-only and editable, and
 * the RENDERED DOM is asserted: raw `href`/`src` attributes and rendered text, never a
 * normalised copy.
 *
 * Two kinds of check:
 *   1. corpus-wide, per note: every `<a href>` either has a door (`openableLinkHref`,
 *      `internalNoteIdFromHref` or `pendingLinkFallbackHref`), is a plain-text placeholder
 *      (`data-link-plain`), or is an attachment download (Task 15: no inert exception);
 *      every stored link survives the editor; every `<img src>` is an attachment URL; no
 *      `import-ref://` survives anywhere; every `importNotice` renders its sentence;
 *   2. ONE named assertion per corpus construct (the table at the bottom).
 */
import { Editor } from '@tiptap/core'
import { afterEach, describe, expect, it } from 'vitest'
import { buildExtensions } from './tiptap'
import {
  openableLinkHref, internalNoteIdFromHref, pendingLinkFallbackHref, isPlainTextPendingLink,
} from './linkClickOpen'
import { importNoticeText, OPEN_ORIGINAL } from './importNoticeText'
import notionCorpus from './importer/__fixtures__/connector_corpora/notion_messy.json'
import obsidianCorpus from './importer/__fixtures__/connector_corpora/obsidian_messy.json'

if (!Range.prototype.getClientRects) Range.prototype.getClientRects = () => []
if (!Range.prototype.getBoundingClientRect) Range.prototype.getBoundingClientRect = () => ({ top: 0, left: 0, right: 0, bottom: 0, width: 0, height: 0 })

const ATTACHMENTS = '/api/j2/notes/attachments/'
// ⚰️ `tel:+15550100` was named here as the one allowed INERT href (kept by the server, no
// door under ruling 165). Plan A Task 15 gave `tel:` a door (`openableLinkHref`), so no
// stored link may be inert any more: every one has a door, is plain text, or is a download.

const CORPORA = { notion_messy: notionCorpus, obsidian_messy: obsidianCorpus }
const ALL = Object.entries(CORPORA).flatMap(([corpus, data]) => Object.entries(data.members)
  .flatMap(([user, member]) => member.notes.map((note) => ({ corpus, user, note }))))

const editors = []
afterEach(() => { while (editors.length) editors.pop().destroy(); document.body.textContent = '' })

function mount(body, editable) {
  const element = document.createElement('div')
  document.body.appendChild(element)
  editors.push(new Editor({ element, editable, extensions: buildExtensions(), content: body }))
  return element
}

function walk(node, out = []) {
  if (node && typeof node === 'object') {
    out.push(node)
    for (const child of node.content || []) walk(child, out)
  }
  return out
}
const storedNodes = (body, type) => walk(body).filter((n) => n.type === type)
const storedLinkHrefs = (body) => storedNodes(body, 'text')
  .flatMap((n) => (n.marks || []).filter((m) => m.type === 'link').map((m) => m.attrs.href))

/** Text-link anchors: not an attachment chip, a notice's "open the original", or an embed bar. */
const textLinks = (root) => [...root.querySelectorAll('a[href]')].filter((a) => a.getAttribute('data-type') !== 'attachmentChip'
  && !a.closest('[data-type="import-notice"]') && !a.closest('[data-type="web-embed"]'))
const linksReading = (root, text) => textLinks(root).filter((a) => a.textContent === text)
const oneLink = (root, text) => {
  const hits = linksReading(root, text)
  expect(hits, `one link reading ${JSON.stringify(text)}`).toHaveLength(1)
  return hits[0]
}

const note = (corpus, user, key) => CORPORA[corpus].members[user].notes.find((n) => n.importKey === key)
const nid = (corpus, user, key) => note(corpus, user, key).id
const noteLink = (id) => `/journal?j2tab=notebook&note=${id}`

describe.each([['read-only', false], ['editable', true]])('connector corpora in the %s editor', (_mode, editable) => {
  describe.each(ALL.map((x) => [`${x.corpus} / ${x.note.title}`, x]))('%s', (_name, { note: n }) => {
    it('every link has a door, is plain text, or is a download', () => {
      const root = mount(n.bodyJson, editable)
      for (const a of root.querySelectorAll('a[href]')) {
        const href = a.getAttribute('href')
        if (a.getAttribute('data-type') === 'attachmentChip') {
          expect(href.startsWith(ATTACHMENTS), href).toBe(true)
        } else if (a.hasAttribute('data-link-plain')) {
          expect(isPlainTextPendingLink(href), href).toBe(true)
        } else {
          const door = openableLinkHref(href) || internalNoteIdFromHref(href) || pendingLinkFallbackHref(href)
          expect(Boolean(door), `no door for ${href}`).toBe(true)
        }
      }
    })

    it('every stored link survives the editor, raw', () => {
      const root = mount(n.bodyJson, editable)
      // Sorted ARRAYS, never Sets: a Set would read two stored links rendered as one (or one
      // rendered twice) as equal. Sorted, because the editor may split one marked run into
      // several anchors only if it also splits the stored run -- the count must match exactly.
      const rendered = textLinks(root).map((a) => a.getAttribute('href')).sort()
      expect(rendered).toEqual([...storedLinkHrefs(n.bodyJson)].sort())
    })

    it('every image is an attachment URL and none is lost', () => {
      const root = mount(n.bodyJson, editable)
      const srcs = [...root.querySelectorAll('img')].map((img) => img.getAttribute('src'))
      expect(srcs).toEqual(storedNodes(n.bodyJson, 'image').map((img) => img.attrs.src))
      for (const src of srcs) expect(src.startsWith(ATTACHMENTS), src).toBe(true)
    })

    it('no import-ref:// placeholder survives', () => {
      const root = mount(n.bodyJson, editable)
      expect(root.innerHTML).not.toContain('import-ref://')
    })

    it('every importNotice renders its sentence', () => {
      const root = mount(n.bodyJson, editable)
      const rendered = [...root.querySelectorAll('[data-type="import-notice"]')]
      const stored = storedNodes(n.bodyJson, 'importNotice')
      expect(rendered).toHaveLength(stored.length)
      stored.forEach((s, i) => {
        const tail = s.attrs.sourceUrl ? ` — ${OPEN_ORIGINAL}` : ''
        expect(rendered[i].textContent).toBe(importNoticeText(s.attrs) + tail)
        const a = rendered[i].querySelector('a')
        expect(a ? a.getAttribute('href') : null).toBe(s.attrs.sourceUrl)
      })
    })
  })
})

// ── one named assertion per construct ──────────────────────────────────────────────

const N = 'notion_messy'
const NU = 'u-notion'
const O = 'obsidian_messy'
const OU = 'u-obsidian'
const HUB = 'notion:11111111-1111-4111-8111-111111111111'
const Q3 = 'notion:22222222-2222-4222-8222-222222222222'
const LATER = 'notion:55555555-5555-4555-8555-555555555555'
const WALL = 'notion:99999999-9999-4999-8999-999999999999'
const DBS = 'notion:aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'
const CAP = 'notion:88888888-8888-4888-8888-888888888888'
const OHUB = 'obsidian:vault-messy/Notes/Hub.md'
const OWALL = 'obsidian:vault-messy/Media wall.md'
const ok = (corpus, user, key) => (key ? note(corpus, user, key).bodyJson : null)
const paragraphOf = (root, starts) => [...root.querySelectorAll('p')].find((p) => p.textContent.startsWith(starts))
/** The top-level block (a direct child of the editor root) holding `el`. */
const topBlock = (el) => {
  let b = el
  while (b.parentElement && !b.parentElement.classList.contains('ProseMirror')) b = b.parentElement
  return b
}
const notices = (root) => [...root.querySelectorAll('[data-type="import-notice"]')].map((d) => d.textContent)

const CONSTRUCTS = [
  ['notion: an in-workspace mention opens the imported note', N, NU, HUB, (root) => {
    expect(internalNoteIdFromHref(oneLink(root, 'Q3 plan (mention)').getAttribute('href'))).toBe(nid(N, NU, Q3))
  }],
  ['notion: every workspace URL form opens the imported note', N, NU, HUB, (root) => {
    const forms = textLinks(root).filter((a) => a.textContent.startsWith('Form '))
    expect(forms).toHaveLength(11)
    for (const a of forms) expect(internalNoteIdFromHref(a.getAttribute('href'))).toBe(nid(N, NU, Q3))
  }],
  ['notion: an unshared target opens notion.so', N, NU, HUB, (root) => {
    const a = oneLink(root, 'Secret')
    expect(a.hasAttribute('data-link-plain')).toBe(false)
    expect(pendingLinkFallbackHref(a.getAttribute('href'))).toBe('https://www.notion.so/77777777777747778777777777777777')
  }],
  ['notion: a trashed target opens notion.so', N, NU, HUB, (root) => {
    expect(pendingLinkFallbackHref(oneLink(root, 'Old idea').getAttribute('href')))
      .toBe('https://www.notion.so/66666666666646668666666666666666')
  }],
  ['notion: a target created later is a note link after the heal', N, NU, Q3, (root) => {
    expect(internalNoteIdFromHref(oneLink(root, 'Later page').getAttribute('href'))).toBe(nid(N, NU, LATER))
  }],
  ['notion: link mentions, previews, bookmarks open the web', N, NU, HUB, (root) => {
    for (const [text, url] of [['Example Domain', 'https://example.com/article'],
      ['https://github.com/octo/repo/pull/7', 'https://github.com/octo/repo/pull/7'],
      ['https://example.com/bookmark', 'https://example.com/bookmark']]) {
      expect(openableLinkHref(oneLink(root, text).getAttribute('href'))).toBe(url)
    }
  }],
  ['notion: bare URLs are links, tickers are not', N, NU, HUB, (root) => {
    const p = paragraphOf(root, 'See ')
    expect([...p.querySelectorAll('a')].map((a) => a.getAttribute('href'))).toEqual([
      'https://example.com/a', 'https://example.com/b', 'https://www.example.org', 'mailto:desk@example.com'])
    expect(p.textContent).toContain('NVDA.US and BRK.B')
  }],
  ['notion: URLs in code and math are not links', N, NU, HUB, (root) => {
    for (const code of root.querySelectorAll('code, pre')) expect(code.querySelector('a')).toBe(null)
    expect([...root.querySelectorAll('pre')].map((p) => p.textContent)).toEqual([
      "fetch('https://example.com/in-codeblock')", 'https://example.com/in-block-math'])
  }],
  ['notion: unsafe schemes are text, //host is https, tel stays', N, NU, HUB, (root) => {
    const p = paragraphOf(root, 'script')
    expect([...p.querySelectorAll('a')].map((a) => [a.textContent, a.getAttribute('href')])).toEqual([
      ['protocol-relative', 'https://evil.example/x'], ['call', 'tel:+15550100'], ['mail', 'mailto:desk@example.com']])
  }],
  ['notion: a HEIC shows the converted image then its original as a chip', N, NU, WALL, (root) => {
    const chip = root.querySelector('a[data-type="attachmentChip"][data-name="IMG_0412.heic"]')
    expect(chip.getAttribute('href')).toMatch(/\.heic$/)
    const before = topBlock(chip).previousElementSibling
    const img = before.tagName === 'IMG' ? before : before.querySelector('img')
    expect(img.getAttribute('src')).toMatch(/^\/api\/j2\/notes\/attachments\/u-notion\/[0-9a-f]{32}\/inline\/[0-9a-f]{32}\.jpg$/)
  }],
  ['notion: an SVG is a file chip, never an inline image', N, NU, WALL, (root) => {
    expect(root.querySelector('a[data-type="attachmentChip"][data-name="logo.svg"]').getAttribute('href')).toMatch(/\.svg$/)
    expect([...root.querySelectorAll('img')].some((img) => img.getAttribute('src').endsWith('.svg'))).toBe(false)
  }],
  ['notion: what could not come over says why', N, NU, WALL, (root) => {
    expect(notices(root)).toEqual([
      `Couldn't copy dead.png — retrying on the next sync — ${OPEN_ORIGINAL}`,
      "gone.png couldn't be found, so it wasn't copied",
      "Couldn't copy stale.png — retrying on the next sync",
      'huge_scan.pdf is too large to copy (limit 25 MB)'])
  }],
  ['notion: YouTube and TradingView play, other videos are links', N, NU, WALL, (root) => {
    expect(root.querySelectorAll('[data-type="web-embed"]')).toHaveLength(2)
    expect(oneLink(root, 'https://vimeo.com/76979871').getAttribute('href')).toBe('https://vimeo.com/76979871')
  }],
  ['notion: video, pdf, audio and file blocks are downloads', N, NU, WALL, (root) => {
    const names = [...root.querySelectorAll('a[data-type="attachmentChip"]')].map((a) => a.getAttribute('data-name'))
    expect(names).toEqual(['IMG_0412.heic', 'logo.svg', 'clip.mp4', 'report.pdf', 'memo.mp3', 'notes.txt'])
  }],
  ['notion: a database is a table whose cells keep their links', N, NU, DBS, (root) => {
    const table = root.querySelector('table')
    const hrefs = [...table.querySelectorAll('a[href]')].filter((a) => !a.hasAttribute('data-type'))
      .map((a) => a.getAttribute('href'))
    expect(hrefs).toEqual(expect.arrayContaining([
      'https://example.com/chart', 'mailto:desk@example.com', 'tel:+15550100', 'https://x.com/p/1',
      noteLink(nid(N, NU, Q3))]))
    expect(table.querySelectorAll('img')).toHaveLength(21)
  }],
  ['notion: capped and truncated databases say so', N, NU, DBS, (root) => {
    expect(notices(root)).toEqual([
      "lost.pdf couldn't be found, so it wasn't copied",
      'Only the first 20 of 22 files in Shots came over',
      'Only the first 2 rows of Endless came over'])
    expect(textLinks(root).filter((a) => a.textContent.startsWith('Log entry '))).toHaveLength(55)
  }],
  ['notion: the media cap reached mid-note leaves storage notices', N, 'u-capped', CAP, (root) => {
    expect(root.querySelectorAll('img')).toHaveLength(1)
    expect(notices(root)).toEqual([
      'Not copied: storage limit. cap_b.png will be copied once space frees up',
      'Not copied: storage limit. cap_c.png will be copied once space frees up'])
  }],
  ['notion: the member-edited note shows what the member wrote', N, NU, 'notion:44444444-4444-4444-8444-444444444444', (root) => {
    expect(root.textContent).toBe('My own notes, written in UCT. Do not overwrite.')
  }],
  ['obsidian: a space-named wikilink opens its note', O, OU, OHUB, (root) => {
    const target = nid(O, OU, 'obsidian:vault-messy/Notes/Target Note.md')
    const hits = linksReading(root, 'Target Note')
    expect(hits).toHaveLength(3)
    for (const a of hits) expect(internalNoteIdFromHref(a.getAttribute('href'))).toBe(target)
  }],
  ['obsidian: an unresolvable wikilink is plain text', O, OU, OHUB, (root) => {
    const a = oneLink(root, 'Ghost Note')
    expect(a.hasAttribute('data-link-plain')).toBe(true)
    expect(pendingLinkFallbackHref(a.getAttribute('href'))).toBe(null)
  }],
  ['obsidian: relative, ../ and deep links open their notes', O, OU, OHUB, (root) => {
    const id = (path) => nid(O, OU, `obsidian:vault-messy/${path}`)
    expect(internalNoteIdFromHref(oneLink(root, 'up a folder').getAttribute('href'))).toBe(id('Archive/Deep.md'))
    expect(internalNoteIdFromHref(oneLink(root, 'space encoded').getAttribute('href'))).toBe(id('Notes/Other note.md'))
    expect(internalNoteIdFromHref(oneLink(root, 'this vault').getAttribute('href'))).toBe(id('Notes/Other note.md'))
    expect(internalNoteIdFromHref(oneLink(root, '100%20club').getAttribute('href'))).toBe(id('100%20club.md'))
    expect(linksReading(root, 'another vault')).toHaveLength(0)
  }],
  ['obsidian: an alias inside a table cell opens its note', O, OU, OHUB, (root) => {
    const a = root.querySelector('table').querySelector('a[href]')
    expect(a.textContent).toBe('table alias')
    expect(internalNoteIdFromHref(a.getAttribute('href'))).toBe(nid(O, OU, 'obsidian:vault-messy/Notes/Other note.md'))
  }],
  ['obsidian: a callout renders as a callout', O, OU, OHUB, (root) => {
    const callout = root.querySelector('[data-variant="warning"]')
    expect(callout).toBeTruthy()
    expect(callout.textContent).toContain('Size it down')
  }],
  ['obsidian: a local attachment says why it did not come over', O, OU, OHUB, (root) => {
    expect(notices(root)).toEqual(["chart one.png can't be shown here"])
  }],
  ['obsidian: refused hotlinks say why, with a link to the original', O, OU, OWALL, (root) => {
    expect(notices(root)).toEqual([
      `bomb.png is too large to copy (limit 25 MB) — ${OPEN_ORIGINAL}`,
      `page.png can't be shown here — ${OPEN_ORIGINAL}`,
      `moved-private.png wasn't copied: its address isn't allowed — ${OPEN_ORIGINAL}`,
      `huge.zip is too large to copy (limit 25 MB) — ${OPEN_ORIGINAL}`,
      `Couldn't copy dead.png — retrying on the next sync — ${OPEN_ORIGINAL}`,
      // Task 15 fix round 1: an unsafe image src, with no original to open.
      "script image wasn't copied: its address isn't allowed"])
  }],
  ['obsidian: copied hotlinks, data: images and raw <img> render', O, OU, OWALL, (root) => {
    expect(root.querySelectorAll('img')).toHaveLength(7)
    expect([...root.querySelectorAll('a[data-type="attachmentChip"]')].map((a) => a.getAttribute('data-name')))
      .toEqual(['md-img-1.svg', 'logo.svg'])
    expect(linksReading(root, 'png as a link')).toHaveLength(0)
  }],
  ['obsidian: a link written before its target existed opens it', O, OU, 'obsidian:vault-messy/Notes/Other note.md', (root) => {
    expect(internalNoteIdFromHref(oneLink(root, 'Later').getAttribute('href')))
      .toBe(nid(O, OU, 'obsidian:vault-messy/Later.md'))
  }],
]

describe.each([['read-only', false], ['editable', true]])('corpus constructs in the %s editor', (_mode, editable) => {
  it.each(CONSTRUCTS)('%s', (_name, corpus, user, key, check) => {
    check(mount(ok(corpus, user, key), editable))
  })
})
